import {project,decodeTerrarium} from './core.mjs';
export const DEM_ZOOM=12;
export const DEM_SOURCE='Mapzen/AWS Terrarium, fixed zoom 12, nearest decoded pixel; native DEM and vertical accuracy vary by region. Grid spacing is not vertical accuracy. https://github.com/tilezen/joerd/blob/master/docs/data-sources.md';
export const ANALYSIS_DEFAULTS={column:'',source:'csv',unit:'sites',title:'',font:15,points:true,counts:true,bands:true,bandStops:'0,1000,2500,3500,9000',bandLabels:'',samples:{}};
export const coordinateKey=p=>`${p.lon},${p.lat}`;
export function elevationColumn(headers){return headers.find(h=>/^(elevation|altitude|elev|elevation_m|altitude_m|海拔|海拔高度|海拔[（(]?m[)）]?|高程)$/i.test(h))||'';}
export function numericElevation(raw){if(typeof raw!=='string'&&typeof raw!=='number')return null;const s=String(raw).trim();if(!s)return null;const n=Number(s);return Number.isFinite(n)&&n>=-12000&&n<=10000?n:null;}
export function quantile(sorted,p){if(!sorted.length)return null;const j=(sorted.length-1)*p,i=Math.floor(j);return sorted[i]+(sorted[Math.min(i+1,sorted.length-1)]-sorted[i])*(j-i);}
export function parseBands(value){const stops=String(value).split(',').map(v=>v.trim());if(stops.length<2||stops.length>13||stops.some(v=>v===''))throw Error('Invalid elevation bands');const numbers=stops.map(Number);if(numbers.some((n,i)=>!Number.isFinite(n)||n< -12000||n>10000||i>0&&n<=numbers[i-1]))throw Error('Invalid elevation bands');return numbers;}
export function validateAnalysis(value){if(value===undefined)return structuredClone(ANALYSIS_DEFAULTS);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Invalid elevation analysis');const out={...structuredClone(ANALYSIS_DEFAULTS),...value};
 if(typeof out.column!=='string'||!['csv','dem','fill'].includes(out.source)||!['sites','records'].includes(out.unit)||typeof out.title!=='string'||out.title.length>160||typeof out.bandLabels!=='string'||out.bandLabels.length>1000||!Number.isFinite(out.font)||out.font<9||out.font>26||['points','counts','bands'].some(k=>typeof out[k]!=='boolean'))throw Error('Invalid elevation analysis');parseBands(out.bandStops);
 if(!out.samples||typeof out.samples!=='object'||Array.isArray(out.samples))throw Error('Invalid elevation analysis');for(const [key,v] of Object.entries(out.samples)){const parts=key.split(',').map(Number);if(parts.length!==2||!parts.every(Number.isFinite)||parts[0]<-180||parts[0]>180||Math.abs(parts[1])>85.05112878||typeof v!=='number'||numericElevation(v)===null)throw Error('Invalid elevation analysis');}return out;
}
export function elevationRows(points,headers,analysis){const index=headers.indexOf(analysis.column);return points.map(p=>{const original=index<0?null:numericElevation(p.row[index]),dem=Object.hasOwn(analysis.samples,coordinateKey(p))?analysis.samples[coordinateKey(p)]:null,value=analysis.source==='csv'?original:analysis.source==='dem'?dem:original??dem;return {...p,original,dem,difference:original!==null&&dem!==null?original-dem:null,value,source:analysis.source==='dem'||original===null?'DEM':'CSV'};});}
export function summarizeElevations(rows,groups,unit='sites'){
 const buckets=new Map(groups.map(g=>[g,[]]));for(const row of rows)if(row.value!==null&&buckets.has(row.group))buckets.get(row.group).push(row);
 return groups.map(group=>{const raw=buckets.get(group),records=raw.length;let values=raw.map(r=>({value:r.value,key:String(r.line)}));if(unit==='sites'){const sites=new Map();for(const r of raw){const key=coordinateKey(r);if(!sites.has(key))sites.set(key,[]);sites.get(key).push(r.value);}values=[...sites].map(([key,vs])=>({key,value:quantile(vs.sort((a,b)=>a-b),.5)}));}const sorted=values.map(v=>v.value).sort((a,b)=>a-b);return {group,n:sorted.length,records,values,min:sorted[0]??null,q1:quantile(sorted,.25),median:quantile(sorted,.5),q3:quantile(sorted,.75),max:sorted.at(-1)??null};});
}
export function pointPixel(point){const n=2**DEM_ZOOM,[u,v]=project(point.lon,point.lat),px=Math.max(0,Math.min(n*256-1,Math.floor(u*n*256))),py=Math.max(0,Math.min(n*256-1,Math.floor(v*n*256)));return {key:`${DEM_ZOOM}/${Math.floor(px/256)}/${Math.floor(py/256)}`,x:px%256,y:py%256};}
export function loadElevationTile(key,signal){return new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';let timer;const finish=(error,data)=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);image.onload=image.onerror=null;error?reject(error):resolve(data);},abort=()=>{image.src='';finish(new Error('Cancelled'));};if(signal?.aborted)return abort();signal?.addEventListener('abort',abort,{once:true});timer=setTimeout(()=>{image.src='';finish(new Error('DEM timeout'));},20000);image.onerror=()=>finish(new Error('DEM unavailable'));image.onload=()=>{try{const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);finish(null,ctx.getImageData(0,0,256,256).data);}catch(e){finish(e);}};image.src=`https://elevation-tiles-prod.s3.amazonaws.com/terrarium/${key}.png`;});}
export async function sampleElevations(points,{samples={},signal,onProgress=()=>{},loadTile=loadElevationTile}={}){
 const tiles=new Map(),result={...samples},failures=[];for(const p of points){const key=coordinateKey(p);if(Object.hasOwn(result,key))continue;const pixel=pointPixel(p);if(!tiles.has(pixel.key))tiles.set(pixel.key,new Map());tiles.get(pixel.key).set(key,pixel);}const jobs=[...tiles],total=jobs.length;let cursor=0,done=0;
 const worker=async()=>{while(cursor<jobs.length&&!signal?.aborted){const [key,locations]=jobs[cursor++];try{const data=await loadTile(key,signal);if(signal?.aborted)break;for(const [coord,{x,y}] of locations){const i=(y*256+x)*4,value=decodeTerrarium(data[i],data[i+1],data[i+2]);if(numericElevation(value)===null)failures.push(coord);else result[coord]=value;}}catch{if(!signal?.aborted)failures.push(...locations.keys());}done++;onProgress({done,total,failed:failures.length});}};await Promise.all(Array.from({length:Math.min(4,total)},worker));return {samples:result,failures,cancelled:!!signal?.aborted};
}
